contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address from, address target, address[] memory tos, uint v) public payable {
        require(tos.length > 0);

        bool reverted;
        bool result;
        uint i;
        for (i = 0; i < tos.length - 1; i++) {
            (bool ok, ) = target.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, tos[i], v));
            require(ok);
        }
        (bool okLast, ) = target.call(abi.encodeWithSelector(bytes4(keccak256("transferFrom(address,address,uint256)")), from, tos[tos.length - 1], v));
        if (okLast) {
            try c.transfer(from, target, tos, v) returns (bool r) {
                result = r;
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.transfer(from, target, tos, v) returns (bool) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        assert(!reverted && result);
    }

    receive() external payable {}
}

